import{f as o,o as e,c as r,a2 as s}from"./chunks/framework.BUDOXiIz.js";const m=JSON.parse('{"title":"Propuestas rechazadas del documento externo \\"NucleoTransversal-Modelo\\"","description":"","frontmatter":{},"headers":[],"relativePath":"revision-externa/NucleoTransversal-rechazados.md","filePath":"revision-externa/NucleoTransversal-rechazados.md","lastUpdated":null}'),n={name:"revision-externa/NucleoTransversal-rechazados.md"};function t(i,a,l,c,d,u){return e(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="propuestas-rechazadas-del-documento-externo-nucleotransversal-modelo" tabindex="-1">Propuestas rechazadas del documento externo &quot;NucleoTransversal-Modelo&quot; <a class="header-anchor" href="#propuestas-rechazadas-del-documento-externo-nucleotransversal-modelo" aria-label="Permalink to &quot;Propuestas rechazadas del documento externo &quot;NucleoTransversal-Modelo&quot;&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Documento revisado</td><td><code>NucleoTransversal-Modelo.md</code> (autor externo, 6-11-2026)</td></tr><tr><td>Informe completo</td><td><code>NucleoTransversal-contraste.md</code>, sección 4.1; evidencia por capítulo en <code>_trabajo/contraste-*.md</code></td></tr><tr><td>Fecha</td><td>10-11-2026</td></tr><tr><td>Estado</td><td>Para comentar. Ninguna de estas propuestas se aplicó a la especificación.</td></tr></tbody></table><h2 id="como-usar-este-documento" tabindex="-1">Cómo usar este documento <a class="header-anchor" href="#como-usar-este-documento" aria-label="Permalink to &quot;Cómo usar este documento&quot;">​</a></h2><p>Son 14 propuestas del documento externo que chocan con decisiones ya tomadas en nuestra especificación. El informe cuenta 15 contradicciones porque algunas filas se repiten (por ejemplo, GestionApps aparece dos veces); los temas distintos son 14.</p><p>En varios casos se rechaza el <strong>medio</strong> que propone el documento, pero su <strong>objetivo</strong> ya está cubierto de otra forma; eso se indica en cada punto.</p><p>Debajo de cada propuesta hay un campo <strong>Comentario</strong> para que escribas tu opinión. Si querés revertir algún rechazo, indicá &quot;Revisar&quot; y se convierte en una decisión nueva.</p><h2 id="resultado-de-la-revision-del-solicitante-10-11-2026" tabindex="-1">Resultado de la revisión del solicitante (10-11-2026) <a class="header-anchor" href="#resultado-de-la-revision-del-solicitante-10-11-2026" aria-label="Permalink to &quot;Resultado de la revisión del solicitante (10-11-2026)&quot;">​</a></h2><p>El solicitante revisó las 14 de a una. Se mantienen 10 rechazos sin cambios (1, 3, 5, 6, 7, 10, 11, 12, 13 y 14). Las otras cuatro quedaron así:</p><ul><li><strong>2. GestionApps:</strong> no se incluye ahora porque no hay información de ese sistema; queda como posible fuente a analizar en el futuro (DEC-108).</li><li><strong>4. Fórmulas en tarifas:</strong> se mantiene el rechazo y se suma la política de preferir reglas declarativas, con justificación obligatoria de cada fórmula y un informe de cuántas reglas usan fórmula (DEC-105).</li><li><strong>8. Vencimientos:</strong> de 1 a 4 por defecto, con el tope como parámetro del tenant validado contra los formatos de los entes de cobro (DEC-106).</li><li><strong>9. Factura rechazada por ARCA:</strong> <strong>se adopta la propuesta del documento externo</strong>: vuelve a borrador y libera su número. Reemplaza DEC-035 en ese punto (DEC-107).</li></ul><hr><h2 id="arquitectura" tabindex="-1">Arquitectura <a class="header-anchor" href="#arquitectura" aria-label="Permalink to &quot;Arquitectura&quot;">​</a></h2><h3 id="_1-instalacion-aislada-por-cooperativa" tabindex="-1">1. Instalación aislada por cooperativa <a class="header-anchor" href="#_1-instalacion-aislada-por-cooperativa" aria-label="Permalink to &quot;1. Instalación aislada por cooperativa&quot;">​</a></h3><ul><li><strong>Qué propone el documento:</strong> cada cooperativa tiene su propia instalación y su propia base de datos (DD-08, capítulos 2.1 y 15).</li><li><strong>Qué decidimos nosotros:</strong> una base única compartida, con cada dato marcado con su cooperativa (<code>tenantId</code>, DEC-002).</li><li><strong>Por qué se rechaza:</strong> es la base del modelo SaaS. Una base por cooperativa es justamente la deuda de ProCoop que reemplazamos.</li></ul><p><strong>Comentario:</strong></p><p> </p><h3 id="_2-gestionapps-como-sistema-base" tabindex="-1">2. GestionApps como sistema base <a class="header-anchor" href="#_2-gestionapps-como-sistema-base" aria-label="Permalink to &quot;2. GestionApps como sistema base&quot;">​</a></h3><ul><li><strong>Qué propone el documento:</strong> tomar GestionApps como base funcional y ProCoop como referencia de lo cooperativo (DD-01).</li><li><strong>Qué decidimos nosotros:</strong> stack propio basado en Connectia (DEC-001) y alcance &quot;todo lo que hace ProCoop&quot; (DEC-007).</li><li><strong>Por qué se rechaza:</strong> GestionApps no es una de nuestras fuentes. Lo que el documento le atribuye (multiempresa, bloqueo por período, saldos calculados, impuestos) ya está cubierto en nuestros anexos.</li></ul><p><strong>Comentario:</strong></p><p> </p><h3 id="_3-claves-foraneas-declaradas-en-la-base" tabindex="-1">3. Claves foráneas declaradas en la base <a class="header-anchor" href="#_3-claves-foraneas-declaradas-en-la-base" aria-label="Permalink to &quot;3. Claves foráneas declaradas en la base&quot;">​</a></h3><ul><li><strong>Qué propone el documento:</strong> declarar en la base de datos una clave foránea para cada relación (capítulo 13.10).</li><li><strong>Qué decidimos nosotros:</strong> MongoDB, que no tiene claves foráneas (DEC-001).</li><li><strong>Por qué se rechaza:</strong> el medio no aplica a nuestro stack. <strong>El objetivo sí se adopta</strong>, con medios propios: cada módulo valida sus referencias, lo emitido guarda una foto de los datos y ahora se suma un verificador nocturno de referencias (DEC-100).</li></ul><p><strong>Comentario:</strong></p><p> </p><hr><h2 id="tarifas-y-comprobantes" tabindex="-1">Tarifas y comprobantes <a class="header-anchor" href="#tarifas-y-comprobantes" aria-label="Permalink to &quot;Tarifas y comprobantes&quot;">​</a></h2><h3 id="_4-prohibir-las-formulas-en-las-tarifas" tabindex="-1">4. Prohibir las fórmulas en las tarifas <a class="header-anchor" href="#_4-prohibir-las-formulas-en-las-tarifas" aria-label="Permalink to &quot;4. Prohibir las fórmulas en las tarifas&quot;">​</a></h3><ul><li><strong>Qué propone el documento:</strong> cargos, recargos y descuentos armados solo con reglas, sin fórmulas libres (capítulo 5.6).</li><li><strong>Qué decidimos nosotros:</strong> primero reglas declarativas y, si no alcanzan, fórmulas en un entorno aislado y seguro (RF-TAR-067, RF-TAR-068).</li><li><strong>Por qué se rechaza:</strong> sin fórmulas no se pueden migrar los cargos reales de ProCoop, como tasas, subsidios y PIST/VAD. Del documento se puede tomar la política de preferir reglas y justificar cada fórmula (mejora de prioridad media, no aplicada).</li></ul><p><strong>Comentario:</strong></p><p> </p><h3 id="_5-un-solo-catalogo-de-ventas-y-compras-con-la-cuenta-contable-en-cada-concepto" tabindex="-1">5. Un solo catálogo de ventas y compras, con la cuenta contable en cada concepto <a class="header-anchor" href="#_5-un-solo-catalogo-de-ventas-y-compras-con-la-cuenta-contable-en-cada-concepto" aria-label="Permalink to &quot;5. Un solo catálogo de ventas y compras, con la cuenta contable en cada concepto&quot;">​</a></h3><ul><li><strong>Qué propone el documento:</strong> un único catálogo por empresa en el que cada concepto lleva su cuenta contable de venta y de compra (capítulo 5.2).</li><li><strong>Qué decidimos nosotros:</strong> cada catálogo tiene su módulo dueño, y las cuentas las asigna contabilidad (M15, AGR-002).</li><li><strong>Por qué se rechaza:</strong> el módulo que vende no debe decidir la contabilidad. Un solo dueño del plan de cuentas permite cambiar la imputación sin tocar los catálogos.</li></ul><p><strong>Comentario:</strong></p><p> </p><h3 id="_6-todos-los-comprobantes-en-una-sola-coleccion" tabindex="-1">6. Todos los comprobantes en una sola colección <a class="header-anchor" href="#_6-todos-los-comprobantes-en-una-sola-coleccion" aria-label="Permalink to &quot;6. Todos los comprobantes en una sola colección&quot;">​</a></h3><ul><li><strong>Qué propone el documento:</strong> todo comprobante, de cualquier clase, con la misma cabecera y en la misma estructura (capítulo 6.3).</li><li><strong>Qué decidimos nosotros:</strong> compartimos la estructura de la cabecera como tipo común, pero cada módulo guarda sus propios documentos (facturas en M05, recibos en M07, órdenes de pago en M12, etc.).</li><li><strong>Por qué se rechaza:</strong> respeta la regla de que cada módulo es dueño de sus datos (RN-DAT-003).</li></ul><p><strong>Comentario:</strong></p><p> </p><h3 id="_7-la-letra-del-comprobante-derivada-dentro-de-un-tipo-generico" tabindex="-1">7. La letra del comprobante derivada dentro de un tipo genérico <a class="header-anchor" href="#_7-la-letra-del-comprobante-derivada-dentro-de-un-tipo-generico" aria-label="Permalink to &quot;7. La letra del comprobante derivada dentro de un tipo genérico&quot;">​</a></h3><ul><li><strong>Qué propone el documento:</strong> la letra (A, B, C) no es un tipo distinto, sino un dato que se deriva de las condiciones fiscales (capítulo 6.1).</li><li><strong>Qué decidimos nosotros:</strong> cada letra es un tipo de comprobante con su código ARCA, y una matriz elige el correcto según la condición fiscal.</li><li><strong>Por qué se rechaza:</strong> ARCA codifica por tipo y letra, así que el modelo sigue esa estructura.</li></ul><p><strong>Comentario:</strong></p><p> </p><h3 id="_8-vencimientos-sin-tope" tabindex="-1">8. Vencimientos sin tope <a class="header-anchor" href="#_8-vencimientos-sin-tope" aria-label="Permalink to &quot;8. Vencimientos sin tope&quot;">​</a></h3><ul><li><strong>Qué propone el documento:</strong> vencimientos y talones de pago como filas, sin cantidad máxima (capítulo 6.5).</li><li><strong>Qué decidimos nosotros:</strong> de 1 a 4 vencimientos por comprobante (RF-FAC-086).</li><li><strong>Por qué se rechaza:</strong> es lo que aceptan ARCA, los códigos de barras y los entes recaudadores. Como el modelo ya guarda los vencimientos como lista, subir el tope sería un cambio de parámetro, no de estructura.</li></ul><p><strong>Comentario:</strong></p><p> </p><h3 id="_9-que-un-comprobante-no-autorizado-vuelva-a-borrador" tabindex="-1">9. Que un comprobante no autorizado vuelva a borrador <a class="header-anchor" href="#_9-que-un-comprobante-no-autorizado-vuelva-a-borrador" aria-label="Permalink to &quot;9. Que un comprobante no autorizado vuelva a borrador&quot;">​</a></h3><ul><li><strong>Qué propone el documento:</strong> si ARCA no autoriza un comprobante numerado, vuelve a borrador (capítulo 7.2).</li><li><strong>Qué decidimos nosotros:</strong> el número se asigna al emitir y, si ARCA rechaza, se reenvía con el mismo número (DEC-035).</li><li><strong>Por qué se rechaza:</strong> volver a borrador deja huecos en la numeración u obliga a renumerar.</li></ul><p><strong>Comentario:</strong></p><p> </p><hr><h2 id="contabilidad-y-compras" tabindex="-1">Contabilidad y compras <a class="header-anchor" href="#contabilidad-y-compras" aria-label="Permalink to &quot;Contabilidad y compras&quot;">​</a></h2><h3 id="_10-impedir-registrar-un-comprobante-sin-cuenta-contable" tabindex="-1">10. Impedir registrar un comprobante sin cuenta contable <a class="header-anchor" href="#_10-impedir-registrar-un-comprobante-sin-cuenta-contable" aria-label="Permalink to &quot;10. Impedir registrar un comprobante sin cuenta contable&quot;">​</a></h3><ul><li><strong>Qué propone el documento:</strong> no se puede registrar ningún comprobante con renglones sin cuenta contable (capítulo 9.3).</li><li><strong>Qué decidimos nosotros:</strong> el asiento queda pendiente y se bloquea el cierre contable hasta resolverlo (PA-CON-02).</li><li><strong>Por qué se rechaza:</strong> frenaría la facturación masiva por un problema de configuración contable.</li></ul><p><strong>Comentario:</strong></p><p> </p><h3 id="_11-todo-el-circuito-de-compras-como-un-unico-documento-que-avanza-por-estados" tabindex="-1">11. Todo el circuito de compras como un único documento que avanza por estados <a class="header-anchor" href="#_11-todo-el-circuito-de-compras-como-un-unico-documento-que-avanza-por-estados" aria-label="Permalink to &quot;11. Todo el circuito de compras como un único documento que avanza por estados&quot;">​</a></h3><ul><li><strong>Qué propone el documento:</strong> un solo documento de compra que pasa por solicitud, cotización, pedido, orden, recepción y factura (capítulo 10.1).</li><li><strong>Qué decidimos nosotros:</strong> documentos separados, vinculados ítem a ítem con sus pendientes (M12).</li><li><strong>Por qué se rechaza:</strong> cada documento tiene efectos distintos: la recepción mueve stock, la factura tiene efectos fiscales y contables. En el circuito, los estados y el vínculo ítem a ítem sí coincidimos.</li></ul><p><strong>Comentario:</strong></p><p> </p><hr><h2 id="seguridad-y-acceso" tabindex="-1">Seguridad y acceso <a class="header-anchor" href="#seguridad-y-acceso" aria-label="Permalink to &quot;Seguridad y acceso&quot;">​</a></h2><h3 id="_12-el-usuario-es-una-persona-del-padron-y-las-contrasenas-se-migran-con-cambio-obligatorio" tabindex="-1">12. El usuario es una persona del padrón y las contraseñas se migran con cambio obligatorio <a class="header-anchor" href="#_12-el-usuario-es-una-persona-del-padron-y-las-contrasenas-se-migran-con-cambio-obligatorio" aria-label="Permalink to &quot;12. El usuario es una persona del padrón y las contraseñas se migran con cambio obligatorio&quot;">​</a></h3><ul><li><strong>Qué propone el documento:</strong> el usuario es una persona del padrón; al migrar, las contraseñas se conservan y se obliga a cambiarlas en el primer ingreso (DD-07, capítulo 12.1).</li><li><strong>Qué decidimos nosotros:</strong> la identidad es global y no se vincula directamente con la persona; las contraseñas no se migran y se envía una invitación de activación (PA-MIG-07, RN-MIG-013).</li><li><strong>Por qué se rechaza:</strong><ul><li>por privacidad entre cooperativas, ya que una misma identidad puede operar en varias;</li><li>ProCoop guarda las contraseñas con cifrado reversible, así que migrarlas arrastraría el riesgo.</li></ul></li></ul><p><strong>Comentario:</strong></p><p> </p><h3 id="_13-secretos-fuera-de-la-base" tabindex="-1">13. Secretos &quot;fuera de la base&quot; <a class="header-anchor" href="#_13-secretos-fuera-de-la-base" aria-label="Permalink to &quot;13. Secretos &quot;fuera de la base&quot;&quot;">​</a></h3><ul><li><strong>Qué propone el documento:</strong> guardar credenciales y secretos fuera de la base de datos (principios del documento).</li><li><strong>Qué decidimos nosotros:</strong> cifrados en MongoDB, con la clave maestra en un servicio de claves externo y fuera de las colecciones de negocio (DEC-074).</li><li><strong>Por qué se rechaza:</strong> más que un rechazo, es una precisión: el objetivo coincide y el medio es distinto.</li></ul><p><strong>Comentario:</strong></p><p> </p><h3 id="_14-elegir-la-empresa-al-iniciar-sesion" tabindex="-1">14. Elegir la empresa al iniciar sesión <a class="header-anchor" href="#_14-elegir-la-empresa-al-iniciar-sesion" aria-label="Permalink to &quot;14. Elegir la empresa al iniciar sesión&quot;">​</a></h3><ul><li><strong>Qué propone el documento:</strong> el usuario elige con qué empresa trabaja al ingresar (capítulo 2.6).</li><li><strong>Qué decidimos nosotros:</strong> la entidad jurídica se resuelve según cada documento (RF-CFG-137).</li><li><strong>Por qué se rechaza:</strong> así un usuario opera varias entidades sin cambiar de sesión.</li></ul><p><strong>Comentario:</strong></p><p> </p><hr><h2 id="comentario-general" tabindex="-1">Comentario general <a class="header-anchor" href="#comentario-general" aria-label="Permalink to &quot;Comentario general&quot;">​</a></h2><p> </p>',76)])])}const g=o(n,[["render",t]]);export{m as __pageData,g as default};
